{
  "name": "oh-my-agentmemory",
  "version": "0.3.0",
  "description": "opencode plugin enforcing agentmemory proactive use via per-turn directives, slot bootstrap, keyword detection, crystal suggestions, and auto-lesson capture",
  "type": "module",
  "main": "./src/adapters/opencode/plugin.ts",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dev-hann/oh-my-agentmemory.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agentmemory",
    "memory",
    "agent",
    "llm"
  ],
  "license": "MIT",
  "files": [
    "src",
    "examples",
    "CHANGELOG.md"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "prepublishOnly": "bun run typecheck && bun run test"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.27",
    "@types/node": "^26.1.2",
    "typescript": "^5.4.0",
    "vitest": "^1.6.0"
  },
  "engines": {
    "bun": ">=1.1.0"
  }
}
